use std::env;

#[derive(Debug)]
enum Command {
    Add(String),
    List,
}

fn parse_args(args: Vec<String>) -> Result<Command, String> {
    match args.get(1).map(String::as_str) {
        Some("add") => args.get(2).cloned().map(Command::Add).ok_or("add needs text"),
        Some("list") => Ok(Command::List),
        _ => Err(String::from("usage: todo add <text> | todo list")),
    }
}

fn main() {
    match parse_args(env::args().collect()) {
        Ok(command) => println!("parsed: {command:?}"),
        Err(err) => {
            eprintln!("{err}");
            std::process::exit(2);
        }
    }
}
